-- ── Keybinds personales ──────────────────────────────────────

-- Terminal con Super + Return

hl.bind("$mainMod" .. " + " .. "Return", hl.dsp.exec_cmd("local_var_TERMINAL"))

-- Firefox

hl.bind("$mainMod" .. " + " .. "F", hl.dsp.exec_cmd("firefox"))

-- Menú de apps

hl.bind("$mainMod" .. " + " .. "space", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/rofi-drun"))

-- Ciclar escritorios

hl.bind("$mainMod + Control" .. " + " .. "Right", hl.dsp.focus({ workspace = "e+1" }))

hl.bind("$mainMod + Control" .. " + " .. "Left", hl.dsp.focus({ workspace = "e-1" }))

-- Gaming — desactivar/activar bloqueo de pantalla

hl.bind("$mainMod" .. " + " .. "F1", hl.dsp.exec_cmd("pkill hypridle && notify-send Idle desactivado"))

hl.bind("$mainMod + Shift" .. " + " .. "F1", hl.dsp.exec_cmd("hypridle & notify-send Idle activado"))

-- Servidor HTTP rápido para transferir archivos en HTB

hl.bind("$mainMod + Alt" .. " + " .. "H", hl.dsp.exec_cmd("kitty --title HTTP Server bash -c cd ~ && python3 -m http.server 8000"))



-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("~/.local/bin/sync-nx-mods.sh")
    hl.exec_cmd("~/.local/bin/sync-totk-mod.sh")
end)

